import json
MODEL = None
TOOLS = None

def configure(model, tools):
    global MODEL, TOOLS
    MODEL, TOOLS = model, tools

def run_icp(icp):
    observations = []
    for _ in range(4):
        decision = MODEL({"icp": icp, "observations": observations})
        if decision["action"] == "finish":
            return decision.get("companies", [])
        if decision["action"] not in ("search", "fetch"):
            return []
        result = TOOLS(decision["action"], decision["arguments"])
        observations.append({"action": decision["action"], "result": result})
    return []
